import {mountArgumentMap} from './argument-map.js';
import {mountWritingHelp} from './wise-help.js';
import {mountTextCoach} from './text-coach.js';
import {mountWordHelp} from './word-help.js';
import {mountWiseFocus} from './focus-flow.js';
export function createWorkbenchUI({api,esc,toast,modal,getState,isCurrent,data,sourceCard,chooseSources,selectAttempt,teachingUI,refresh}) {
 const $=s=>document.querySelector(s), nodeLink=id=>'#paper/'+encodeURIComponent(id);
 let generation=0,lastSerial;
 const get=(key,fallback=null)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
 const put=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
 const draftGet=key=>{try{return localStorage.getItem(key)}catch{return null}};
 const draftPut=(key,value)=>{try{localStorage.setItem(key,value);return true}catch{return false}};
 const remove=key=>{try{localStorage.removeItem(key)}catch{}};
 const questions={I:'Why is an explained review priority needed?',II:'What is established, and what remains to be connected?',III:'What must a solution make possible?',IV:'How does WISE provide the required capability?',V:'What was tested, and what does the evidence support?',VI:'What follows, within which limitations?',AB:'What problem, contribution and bounded result should the abstract summarise?'};
 const handovers={I:'The problem defines what the literature must examine.',II:'The foundations and gap motivate the required capabilities.',III:'The requirements constrain the method in IV.',IV:'The mechanisms define what the evaluation must examine.',V:'The evidence bounds the discussion and conclusions.',VI:'Answer the research question within the demonstrated scope.',AB:'Summarise the argument after checking the paper.'};
 const fields={reader_before:'What the reader already knows',contribution:'What this paragraph adds',bridge:'The reason connecting my ideas',handover:'What the next paragraph needs to explain',open_question:'An unresolved claim or evidence question',next_action:'My next writing action'};
 const evidenceLabels={open_question:'Open evidence question',linked_unassessed:'Linked · not assessed',supports:'Supports the stated claim · author assessment',supports_narrower:'Supports a narrower claim · author assessment',does_not_support:'Does not support this claim · author assessment'};
 const practiceLink=(key,id)=>'#practice/'+encodeURIComponent(key)+'?from='+encodeURIComponent(id);
 const order=(p,section,manuscript=false)=>(manuscript?p.workbench.manuscript_orders:p.workbench.orders)[section]||p.blueprint.nodes.filter(n=>n.section===section).map(n=>n.id);
 const node=(p,id)=>p.blueprint.nodes.find(n=>n.id===id);
 const evidenceFor=(p,ids)=>Object.values(p.workbench.evidence).filter(e=>e.node_ids.some(id=>ids.includes(id)));
 function marks(p,id){const d=p.drafts[id],s=p.selected[id],q=p.workbench.plans[id]?.open_question;return `<span class="wb-mark ${s?'chosen':''}">${s?'✓ Version selected':d?'✎ Draft saved':'○ No saved draft'}</span>${s&&d&&d.id!==s.id&&d.created>s.created?'<span class="wb-mark">Newer draft available</span>':''}${q?'<span class="wb-mark question">? Open question</span>':''}`}
 function shell(p,section,view,activeId){
  const resume=get('awl-writing-resume',null),fallback=p.blueprint.nodes.find(n=>!p.selected[n.id])?.id||'I-01';
  const target=p.blueprint.nodes.some(n=>n.id===resume)?resume:fallback;
  return `<div class="wb-shell"><header class="wb-header"><div><div class="eyebrow">YOUR PAPER / WISE</div><h1>${view==='desk'?'Build one clear step in the argument':view==='evidence'?'Connect claims to evidence':view==='read'?'Read the argument you wrote':'See how the argument fits together'}</h1></div><div class="wb-intentions"><a class="btn secondary" href="#paper">Write WISE</a><a class="btn quiet" href="#courses">Practise English</a></div></header><div class="wb-toolbar"><nav class="wb-tabs" aria-label="Ways to work on WISE"><a class="${view==='flow'?'current':''}" href="#paper/flow-${esc(activeId||target)}">Whole argument</a><a class="${view==='map'?'current':''}" href="#paper/section-${section}">Argument map</a><a class="${view==='desk'?'current':''}" href="${nodeLink(activeId||target)}">Paragraph desk</a><a class="${view==='evidence'?'current':''}" href="#paper/evidence-1">Evidence chain</a><a class="${view==='read'?'current':''}" href="#paper/read-${section}">Read & revise</a><a href="#revision">Discussion & existing text</a></nav><span class="tiny">${p.selected_count} versions selected · ${p.blueprint.nodes.length} proposed targets</span></div><div id="wb-stage"></div><footer class="wb-footer"><a href="/api/paper/plan-export">Download argument notes</a><a href="/api/paper/export">Download selected manuscript</a><button class="btn quiet" id="wb-vault-export">Save manuscript to Obsidian</button><a href="/api/paper/readings/OVERVIEW" target="_blank" rel="noreferrer">Open supplied overview</a><span>Planning, writing and evidence are separate records.</span></footer></div>`;
 }
 async function render(id,serial){
  if(serial!==undefined)lastSerial=serial;
  const token=++generation,route=lastSerial,current=()=>token===generation&&(route===undefined||isCurrent(route));
  const p=await data();if(!current())return;
  const n=node(p,id);
  let section=n?.section||id?.match(/^(?:section|read)-(I|II|III|IV|V|VI|AB)$/)?.[1]||get('awl-paper-section','I');
  if(!p.blueprint.sections[section])section='I';
  const view=n?'desk':id?.startsWith('flow-')?'flow':id?.startsWith('evidence-')?'evidence':id?.startsWith('read-')?'read':'map';
  $('#main').innerHTML=shell(p,section,view,n?.id);put('awl-paper-section',section);
  $('#wb-vault-export').onclick=async()=>{try{const r=await api('/paper/export/vault',{});toast('Your selected writing was exported to '+r.path)}catch(e){toast(e.message)}};
  if(n){put('awl-writing-resume',n.id);window.dispatchEvent(new CustomEvent('awl-paper-open',{detail:{id:n.id,title:n.title}}));await desk(p,n,current)}
  else if(view==='flow')mountArgumentMap($('#wb-stage'),p,id.slice(5),esc);
  else if(view==='evidence')evidence(p,id==='evidence-all'?0:Math.max(1,Math.min(6,Number(id.split('-')[1])||1)),current);
  else if(view==='read')read(p,section,current);
  else map(p,section,current);
 }
 const targetForMap=p=>p.blueprint.nodes.some(n=>n.id===get('awl-writing-resume'))?get('awl-writing-resume'):'I-06';
 function map(p,section,current){
  const ids=order(p,section),plans=p.workbench.plans,hasOrder=JSON.stringify(ids)!==JSON.stringify(order(p,section,true));
  $('#wb-stage').innerHTML=`<a class="btn secondary" href="#paper/flow-${esc(targetForMap(p))}">See the whole argument visually →</a><div class="wb-spine" aria-label="WISE argument and reading order">${['I','II','III','IV','V','VI'].map(s=>`<a href="#paper/section-${s}" class="wb-section ${section===s?'current':''}" ${section===s?'aria-current="page"':''}><span>${s}</span><strong>${esc(p.blueprint.sections[s])}</strong><small>${esc(questions[s])}</small></a>`).join('')}</div><p class="tiny">Arrows show reading and argument order, not causal effects. <a href="#paper/section-AB">Abstract</a></p><div class="wise-directions"><strong>New discussion and manuscript available</strong><p>The older overview is a working plan. Review the new discussion directions and preserve agreed passages before expanding it.</p><a href="#revision">Open the revision workspace →</a></div><div class="wb-section-job"><strong>${esc(questions[section])}</strong><span>${esc(handovers[section])}</span></div><div class="section-row"><div><h2>${esc(p.blueprint.sections[section])} storyboard</h2><p class="tiny">${ids.length} proposed targets. A target can contribute to a paragraph; the target count is not a required paragraph count.</p></div><a class="btn" href="${nodeLink(get('awl-writing-resume')&&ids.includes(get('awl-writing-resume'))?get('awl-writing-resume'):ids[0])}">Continue writing →</a></div>${section==='II'?'<div class="wb-section-branches"><span>Analysis role A · Evidence of the problem</span><span>Analysis role B · Foundations for a solution</span><span>Both inform the integrative gap</span></div>':''}<ol class="wb-storyboard">${ids.map((id,index)=>{const n=node(p,id),plan=plans[id]||{};return `<li class="wb-story-card"><div class="section-row"><span class="tag">${esc(id)}</span><div class="wb-move"><button type="button" class="btn quiet" data-move="${id}" data-shift="-1" aria-label="Move ${id} earlier" ${index===0?'disabled':''}>↑</button><button type="button" class="btn quiet" data-move="${id}" data-shift="1" aria-label="Move ${id} later" ${index===ids.length-1?'disabled':''}>↓</button></div></div><a href="${nodeLink(id)}"><h3>${esc(n.title)}</h3></a><p class="wb-purpose">${esc(n.purpose)}</p>${plan.contribution?`<p><small>My intended point</small><br>${esc(plan.contribution)}</p>`:''}<div class="wb-markers">${marks(p,id)}</div>${plan.next_action?`<p class="tiny"><strong>Next:</strong> ${esc(plan.next_action)}</p>`:''}<a class="wb-open" href="${nodeLink(id)}">Open writing desk →</a><div class="wb-card-handover"><span>→ ${esc(ids[index+1]||'Next section')}</span> ${esc(plan.handover||'What does the next unit need from this one?')}</div></li>`}).join('')}</ol><div class="wb-order-actions"><p>${hasOrder?'Your planning order differs from the manuscript order. Read it as a proposal before applying it.':'Planning and manuscript order currently match.'}</p><button class="btn secondary" id="wb-apply-order" ${!hasOrder?'disabled':''}>Apply planned order to manuscript</button><button class="btn quiet" id="wb-reset-order">Restore overview order in plan</button><span id="wb-order-status" role="status"></span></div><details class="card"><summary>Source alternatives and reading support</summary><p>Keep alternative source cards outside the manuscript until you choose the ideas to use. Open a paragraph desk to inspect and select cards.</p><a class="btn secondary" href="#reader">WISE source-reader reviews</a><p>${esc(p.blueprint.counting_note)}</p></details>`;
  document.querySelectorAll('[data-move]').forEach(b=>b.onclick=async()=>{
   const moved=[...ids],i=moved.indexOf(b.dataset.move),j=i+Number(b.dataset.shift);[moved[i],moved[j]]=[moved[j],moved[i]];
   b.disabled=true;try{p.workbench=await api('/paper/plan-order/'+section,{base_version:p.workbench.version,node_ids:moved},'PUT');if(current()){map(p,section,current);toast('Planning order saved. Manuscript order changes only when you apply it.');document.querySelector(`[data-move="${b.dataset.move}"][data-shift="${b.dataset.shift}"]`)?.focus()}}catch(e){toast(e.message);b.disabled=false}
  });
  $('#wb-reset-order').onclick=async()=>{try{p.workbench=await api('/paper/plan-order/'+section,{base_version:p.workbench.version,node_ids:p.blueprint.nodes.filter(n=>n.section===section).map(n=>n.id)},'PUT');if(current())map(p,section,current)}catch(e){toast(e.message)}};
  $('#wb-apply-order').onclick=()=>{modal('Apply this section order',`<p>Use this sequence when reading and exporting selected manuscript versions. Your saved text and the supplied overview stay available.</p><ol>${ids.map(id=>`<li>${esc(id)} · ${esc(node(p,id).title)}</li>`).join('')}</ol><button class="btn" id="wb-confirm-order">Apply this order</button><p id="wb-apply-status" role="status"></p>`);$('#wb-confirm-order').onclick=async()=>{try{p.workbench=await api('/paper/apply-order/'+section,{base_version:p.workbench.version});$('#modal').close();if(current())map(p,section,current);toast('Manuscript reading and export order updated.')}catch(e){$('#wb-apply-status').textContent=e.message}}};
 }
 async function desk(p,n,current){
  const created=await api('/sessions',{exercise_key:n.draft_exercise_key});if(!current())return;
  let session=await api('/sessions/'+created.id);if(!current())return;
  const cache='awl-draft-'+n.draft_exercise_key,planKey='awl-plan-'+n.id;
  const stored=get(planKey),plan=stored?.fields||p.workbench.plans[n.id]||{};
  let planVersion=stored?.base_version??p.workbench.version,requestKey=null;
  const ids=n.section==='AB'?order(p,'AB'):['I','II','III','IV','V','VI'].flatMap(section=>order(p,section)),index=ids.indexOf(n.id),previous=node(p,ids[index-1]),next=node(p,ids[index+1]);
  const exercises=getState().exercises.filter(e=>e.paper_node_id===n.id&&!e.archived_version),drill=exercises.find(e=>e.stage_index===5);
  const chosen=p.state.nodes[n.id]?.source_ids||[],evid=evidenceFor(p,[n.id]);
  $('#wb-stage').innerHTML=`<div class="wb-desk-heading"><div><span class="tag">${n.id}</span><h2>${esc(n.title)}</h2><p>${esc(n.purpose)}</p></div><a href="#paper/section-${n.section}">← Section storyboard</a><button class="btn secondary wb-mobile-jump" id="wb-jump-writing">Go to my paragraph ↓</button></div><nav class="wise-position-nav" aria-label="Jump between argument moves">${previous?`<a href="${nodeLink(previous.id)}">← ${esc(previous.id)}</a>`:"<span>Start of section</span>"}<a href="#paper/flow-${esc(n.id)}">Whole argument · you are at ${esc(n.id)}</a>${next?`<a href="${nodeLink(next.id)}">${esc(next.id)} →</a>`:"<span>End of section</span>"}</nav><div class="wb-neighbours"><div><small>Before this unit</small>${previous?`<a href="${nodeLink(previous.id)}">${esc(previous.title)}</a>`:'Introduce the review problem.'}</div><div><small>After this unit</small>${next?`<a href="${nodeLink(next.id)}">${esc(next.title)}</a>`:esc(handovers[n.section])}</div></div><div class="wb-desk-grid"><section class="card wb-brief"><p class="text-role teaching">Teaching help · argument prompts</p><h3>Build the reason</h3><p class="tiny">These prompts describe a possible argument. They are not sentences from your manuscript.</p><div class="wb-idea-flow">${n.ideas.map((idea,i)=>`<div class="wb-idea"><small>Idea ${i+1}</small>${esc(idea)}</div>${i<n.ideas.length-1?'<span class="wb-join">↓ What connects these ideas?</span>':''}`).join('')}</div><div class="note-strip"><strong>Claim boundary</strong><p>${esc(n.boundary)}</p></div>${n.id==='I-01'?'<p class="reader-question">What makes some review targets more relevant to the objective than others? Limited capacity alone explains the need to choose; it does not establish which evidence should determine the choice.</p>':''}<details><summary>A reasoning example from another field</summary><div class="worked-answer"><p><strong>Goal:</strong> volunteers want to find garden beds that may need water.</p><p><strong>Constraint:</strong> they can inspect only six today.</p><p><strong>Connecting premise:</strong> signs of dryness may identify beds worth inspecting earlier. That is an assumption to check.</p><p><strong>Consequence:</strong> use those signs to order inspections, then check whether watering is needed.</p><p class="tiny">Original teaching example. Supply the reason in your own topic, not just a word such as “therefore”.</p></div></details><details id="wb-source-drawer"><summary>Archived idea cards · ${chosen.length} chosen by you</summary><p class="tiny">Earlier notes and analysis, which may contain LLM wording. These are different from the uploaded manuscript and are not automatically agreed prose. Use them to recover ideas and citation keys.</p><button class="btn secondary" id="wb-choose-sources">Find and choose cards</button><div class="source-links">${(chosen.length?chosen:n.source_card_ids).map(id=>`<button class="btn quiet" data-source="${esc(id)}">${esc(id)}</button>`).join('')}</div><small>${chosen.length?'Chosen by you; evidence still needs checking.':'Topic suggestions; no cards selected yet.'}</small></details><details class="wb-phrasebook" open><summary>Phrasebank · language for my argument</summary><div id="wb-phrasebook"></div></details><details><summary>Language and academic-writing support</summary><div id="wb-toolbox"></div></details><details><summary>Reading and supervisor direction</summary>${p.blueprint.books.filter(book=>n.book_ids.includes(book.id)).map(book=>`<p><a href="/api/paper/readings/${esc(book.id)}" target="_blank" rel="noreferrer">${esc(book.title)}</a><br><small>${esc(book.reading)} · ${esc(book.principle)}</small></p>`).join('')}<p class="tiny">Supervisor comment locators: ${esc(n.supervisor_comment_ids.join(', '))}.</p></details><details><summary>Neighbouring selected prose</summary>${[previous,next].filter(Boolean).map(nn=>`<h3>${esc(nn.id)} · ${esc(nn.title)}</h3><p class="prose">${esc(p.selected[nn.id]?.text||'No manuscript version selected.')}</p>`).join('')||'<p>No neighbouring target in this section.</p>'}</details><p class="tiny">Overview p. ${n.overview_pages.join(', ')} · ${evid.length} evidence records linked to this target · <a href="#paper/evidence-all">See all evidence records</a></p></section><section class="card wb-editor"><div id="wise-node-support"></div><h3>My meaning, then my sentences</h3><button class="btn quiet wb-focus-notes" id="wb-plan-toggle" aria-expanded="false">Show / hide argument notes</button><div class="wb-plan-fields">${['contribution','bridge','handover'].map(field=>`<label class="field">${fields[field]}<textarea rows="2" maxlength="3000" data-plan="${field}">${esc(plan[field]||'')}</textarea></label>`).join('')}<details><summary>Context, unresolved questions and next action</summary>${['reader_before','open_question','next_action'].map(field=>`<label class="field">${fields[field]}<textarea rows="2" maxlength="3000" data-plan="${field}">${esc(plan[field]||'')}</textarea></label>`).join('')}</details><div class="actions"><button class="btn secondary" id="wb-save-plan">Save argument notes</button><span id="wb-plan-status" class="tiny" role="status">${stored?'Browser notes recovered; save to record them on this Mac.':'Your notes are separate from manuscript prose.'}</span></div></div><section class="wise-scratchpad"><h3>My notes & outline</h3><p class="tiny">Ideas, questions and rough wording for ${esc(n.id)}. These notes are saved separately and are not included in the manuscript.</p><label class="field">Notes for this paragraph<textarea id="wb-notes" data-plan="scratchpad" rows="4" maxlength="3000" placeholder="Plan the point here; write your paragraph in My paragraph text.">${esc(plan.scratchpad||'')}</textarea></label><div class="actions"><button class="btn secondary" id="wb-save-notes">Save notes</button><button class="btn quiet" id="wb-copy-to-notes">Copy current text to notes</button></div><p id="wb-notes-status" class="tiny" role="status"></p></section><label class="field wb-prose-label">My paragraph text · editable<textarea id="wb-draft" rows="9" maxlength="12000" placeholder="Write from your own ideas. You can leave a question where evidence is still needed."></textarea></label><div class="editor-meta"><span id="wb-draft-status" role="status">${session.attempts.length} saved versions</span><span id="wb-words"></span></div><div class="actions"><button class="btn" id="wb-save-draft">Save paragraph version</button><button class="btn secondary" id="wb-select-version" ${!session.attempts.length?'disabled':''}>Choose manuscript version</button></div><div class="actions"><a class="btn secondary" href="${practiceLink(n.draft_exercise_key,n.id)}">Review with the tutor</a>${drill?`<a class="btn quiet" href="${practiceLink(drill.key,n.id)}">Practise the bridge, then return</a>`:''}</div><div class="wb-markers" id="wb-draft-marks">${marks(p,n.id)}</div><details ${p.selected[n.id]?.document_id?'open':''} class="wb-selected-version"><summary>Text currently selected for WISE · saved copy</summary>${p.selected[n.id]?.document_id?`<p class="tiny">${p.selected[n.id].mode==='keep'?'Retained manuscript text':'Your adaptation of manuscript text'} · source and earlier versions preserved</p><a class="btn secondary" href="#revision/${n.id}?reuse=${p.selected[n.id].id}">Edit a copy of this selected passage</a>`:''}<p class="prose">${esc(p.selected[n.id]?.text||'No version selected. Save your paragraph and choose the version to include.')}</p>${p.selected[n.id]?'<button class="btn quiet" id="wb-unselect">Remove this selection</button>':''}</details><a href="#paper/read-${n.section}">Read selected prose in context →</a><details><summary>Other exercises for this paragraph</summary><div class="target-activities">${exercises.map(e=>`<a href="${practiceLink(e.key,n.id)}">${e.stage_index}. ${esc(e.title)}${getState().learning?.exercise_status[e.key]?.completed?' · ✓ Complete':''}</a>`).join('')}</div></details></section></div>`;
  mountWritingHelp({api,esc,host:$('#wise-node-support'),node:n,paper:p,current}).catch(e=>toast(e.message));
  $('#wb-plan-toggle').onclick=()=>{const open=$('.wb-plan-fields').classList.toggle('focus-plan-open');$('#wb-plan-toggle').setAttribute('aria-expanded',String(open))};
  const editor=$('#wb-draft'),cached=draftGet(cache);editor.value=cached??session.text;
  $('#wb-jump-writing').onclick=()=>{editor.scrollIntoView({behavior:'smooth',block:'center'});editor.focus({preventScroll:true})};
  function draftChanged(){requestKey=null;const saved=draftPut(cache,editor.value);$('#wb-words').textContent=editor.value.trim()?editor.value.trim().split(/\s+/).length+' words':'0 words';$('#wb-draft-status').textContent=saved?(editor.value===session.text?'Matches the last saved version.':'Draft kept in this browser · save a version to record it on this Mac.'):'Browser storage unavailable; save a paragraph version.'}
  editor.oninput=draftChanged;draftChanged();
  if(p.selected[n.id]?.document_id){const selected=$('.wb-selected-version');$('.wb-prose-label').before(selected);$('.wb-prose-label').firstChild.textContent='My separate paragraph text · editable';}
  function planFields(){return Object.fromEntries([...document.querySelectorAll('[data-plan]')].map(x=>[x.dataset.plan,x.value]))}
  function noteStatus(text){$('#wb-plan-status').textContent=text;$('#wb-notes-status').textContent=text}
  noteStatus($('#wb-plan-status').textContent);
  document.querySelectorAll('[data-plan]').forEach(input=>input.oninput=()=>{noteStatus(put(planKey,{base_version:planVersion,fields:planFields()})?'Notes kept in this browser · save to record them.':'Browser storage unavailable; save your notes.')});
  $('#wb-save-plan').onclick=async()=>{const button=$('#wb-save-plan');if(button.disabled)return;button.disabled=true;$('#wb-save-notes').disabled=true;const submitted=planFields();try{p.workbench=await api('/paper/plans/'+n.id,{base_version:planVersion,...submitted},'PUT');planVersion=p.workbench.version;if(current()){if(JSON.stringify(planFields())===JSON.stringify(submitted)){remove(planKey);noteStatus('Notes saved on this Mac.');}else{put(planKey,{base_version:planVersion,fields:planFields()});noteStatus('Previous notes saved; newer edits remain in this browser.');}}}catch(e){if(current())noteStatus(e.message)}finally{if(current()){button.disabled=false;$('#wb-save-notes').disabled=false}}};
  $('#wb-save-notes').onclick=()=>$('#wb-save-plan').click();
  $('#wb-copy-to-notes').onclick=()=>{const notes=$('#wb-notes'),text=[notes.value,editor.value].filter(Boolean).join('\n\n');if(text.length>notes.maxLength){noteStatus('These notes would exceed 3,000 characters. Copy a shorter part instead.');return}notes.value=text;notes.dispatchEvent(new Event('input'));notes.focus()};
  $('#wb-save-draft').onclick=async()=>{const button=$('#wb-save-draft');if(!editor.value.trim()){editor.focus();$('#wb-draft-status').textContent='Write your paragraph first.';return}button.disabled=true;requestKey||=crypto.randomUUID();try{const r=await api('/submit',{exercise_key:n.draft_exercise_key,session_id:session.id,text:editor.value,outline:session.outline,request_key:requestKey,base_version:session.version,request_feedback:false});session=await api('/sessions/'+r.session_id);requestKey=null;if(!current())return;$('#wb-select-version').disabled=false;$('#wb-draft-status').textContent=`Version ${r.attempt_count} saved. Manuscript selection stays as you chose it.`;p.drafts[n.id]=session.attempts.at(-1);$('#wb-draft-marks').innerHTML=marks(p,n.id);if(refresh)await refresh()}catch(e){if(current())$('#wb-draft-status').textContent=e.message}finally{if(current())button.disabled=false}};
  editor.onkeydown=event=>{if(event.key==='Enter'&&(event.metaKey||event.ctrlKey)){event.preventDefault();if(!event.repeat)$('#wb-save-draft').click()}};
  $('#wb-select-version').onclick=()=>selectAttempt(n.id,session.attempts,async()=>{if(current())await render(n.id)}).catch(e=>toast(e.message));
  $('#wb-choose-sources').onclick=()=>chooseSources(n,p);
  document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceCard(b.dataset.source).catch(e=>toast(e.message)));
  if($('#wb-unselect'))$('#wb-unselect').onclick=async()=>{try{await api('/paper/nodes/'+n.id,{base_version:p.state.version,clear_selection:true},'PUT');if(current())await render(n.id)}catch(e){toast(e.message)}};
  await Promise.all([teachingUI.toolbox(n.id,$('#wb-toolbox'),current),teachingUI.mountPhrasebook($('#wb-phrasebook'),n.id,current,text=>{editor.value+=(editor.value&&!editor.value.endsWith('\n')?'\n':'')+text;editor.dispatchEvent(new Event('input'));editor.focus();})]);
  let argument=null;try{argument=await api('/revision/argument/'+n.id)}catch(e){if(current())toast('Argument context could not load: '+e.message)}
  if(current()){mountWiseFocus(n,p,argument,esc);mountWordHelp({api,esc,node:n,editors:[editor,$('#wb-notes')],current});mountTextCoach({api,esc,editor,exerciseKey:n.draft_exercise_key,nodeId:n.id,current});}
 }
 function evidence(p,number,current){
  const keys=number?['II-B'+number,'III-S'+number,'IV-M'+number]:p.blueprint.nodes.map(n=>n.id),items=evidenceFor(p,keys);
  $('#wb-stage').innerHTML=`<p>Follow the overview's foundations, requirements and mechanisms. Evidence links record your assessment of specific claims. <a href="#paper/evidence-all">See all evidence records</a></p><div class="wb-chain-head"><span>II · motivates</span><span>III · requires</span><span>IV · operationalises</span><span>V · examines</span></div><div class="wb-chains">${[1,2,3,4,5,6].map(i=>{const ids=['II-B'+i,'III-S'+i,'IV-M'+i],links=evidenceFor(p,ids),open=links.filter(e=>e.status==='open_question').length;return `<a class="wb-chain ${i===number?'current':''}" href="#paper/evidence-${i}" ${i===number?'aria-current="page"':''}>${ids.map(id=>`<span><small>${id}</small>${esc(node(p,id).title)}</span>`).join('')}<span>${links.length?links.length+' claim records'+(open?' · '+open+' open':''):'○ Evidence not linked'}</span></a>`}).join('')}</div><section class="card"><div class="section-row"><h2>${number?esc(node(p,keys[1]).title):'All evidence questions and links'}</h2><button class="btn" id="wb-add-evidence">Add a claim or evidence question</button></div><div class="wb-evidence-detail">${(number?keys:[]).map(id=>{const n=node(p,id);return `<div><a href="${nodeLink(id)}">${esc(n.title)}</a><ul>${n.ideas.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`}).join('')}</div><p class="reader-question">Which part of the mechanism provides this capability, and what observation or artefact supports that claim? Record what the evidence does not establish.</p><div id="wb-evidence-records">${items.length?items.map(e=>`<article class="wb-evidence-record"><span class="wb-mark ${e.status==='open_question'?'question':''}">${esc(evidenceLabels[e.status])}</span><h3>${esc(e.claim)}</h3><p><strong>Locator:</strong> ${esc(e.locator||'Not yet recorded')}</p><p><strong>Reason:</strong> ${esc(e.rationale||'Assessment still needed')}</p><p><strong>Boundary:</strong> ${esc(e.boundary||'Not yet recorded')}</p><p class="tiny">Targets: ${esc(e.node_ids.join(', '))}</p><button class="btn secondary" data-edit-evidence="${esc(e.id)}">Edit this record</button></article>`).join(''):'<p>No evidence record linked to this row yet. This does not mean that the research has no evidence.</p>'}</div><a href="#paper/V-05">Open evaluation coverage paragraph →</a></section>`;
  $('#wb-add-evidence').onclick=()=>editEvidence(p,number?keys:['III-S1','IV-M1'],number,current);
  document.querySelectorAll('[data-edit-evidence]').forEach(b=>b.onclick=()=>editEvidence(p,keys,number,current,p.workbench.evidence[b.dataset.editEvidence]));
 }
 function editEvidence(p,keys,number,current,record){
  const chosen=record?.node_ids||[...keys,'V-05'];
  modal(record?'Edit evidence record':'Record a claim or question',`<label class="field">Claim or question<textarea id="wb-evidence-claim" rows="3" maxlength="3000">${esc(record?.claim||'')}</textarea></label><label class="field">Targets this concerns<select id="wb-evidence-targets" multiple size="6">${p.blueprint.nodes.map(n=>`<option value="${n.id}" ${chosen.includes(n.id)?'selected':''}>${n.id} · ${esc(n.title)}</option>`).join('')}</select><small>Use Cmd/Ctrl to select several targets; up to twelve.</small></label><label class="field">Evidence status<select id="wb-evidence-status">${Object.entries(evidenceLabels).map(([key,label])=>`<option value="${key}" ${key===(record?.status||'open_question')?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Exact source or artefact locator<input id="wb-evidence-locator" maxlength="2000" value="${esc(record?.locator||'')}" placeholder="Citation key + page, table, run/configuration ID or file location"></label><label class="field">Why it supports this assessment<textarea id="wb-evidence-rationale" rows="3" maxlength="3000">${esc(record?.rationale||'')}</textarea></label><label class="field">Scope or limitation<textarea id="wb-evidence-boundary" rows="2" maxlength="2000">${esc(record?.boundary||'')}</textarea></label><p class="tiny">These are your recorded judgements. A link alone does not verify a claim.</p><button class="btn" id="wb-save-evidence">Save evidence record</button><p id="wb-evidence-error" role="status"></p>`);
  $('#wb-save-evidence').onclick=async()=>{const button=$('#wb-save-evidence');button.disabled=true;try{const body={base_version:p.workbench.version,node_ids:[...$('#wb-evidence-targets').selectedOptions].map(o=>o.value),claim:$('#wb-evidence-claim').value,locator:$('#wb-evidence-locator').value,rationale:$('#wb-evidence-rationale').value,boundary:$('#wb-evidence-boundary').value,status:$('#wb-evidence-status').value};p.workbench=await api('/paper/evidence'+(record?'/'+record.id:''),body,record?'PUT':'POST');$('#modal').close();if(current())evidence(p,number,current);toast('Evidence record saved.')}catch(e){$('#wb-evidence-error').textContent=e.message}finally{button.disabled=false}};
 }
 function read(p,section,current){
  const ids=order(p,section,true);
  $('#wb-stage').innerHTML=`<div class="section-row"><div><h2>${esc(p.blueprint.sections[section])}</h2><p>Read only the versions selected for your manuscript. Compare each paragraph's intended job with its actual point.</p></div><label class="field">Section<select id="wb-read-section">${Object.entries(p.blueprint.sections).map(([s,title])=>`<option value="${s}" ${s===section?'selected':''}>${s} · ${esc(title)}</option>`).join('')}</select></label></div><label class="checkbox-row"><input type="checkbox" id="wb-outline-toggle" checked>Show argument jobs and my reverse outline</label><label class="checkbox-row"><input type="checkbox" id="wb-gaps-toggle" ${document.body.classList.contains('focus-mode')?'':'checked'}>Show targets with no selected text (${ids.filter(id=>!p.selected[id]).length})</label>${ids.every(id=>!p.selected[id])?'<p>No manuscript text is selected in this section yet. Open the storyboard to choose one passage.</p>':''}<div class="wb-reading">${ids.map(id=>{const n=node(p,id),a=p.selected[id],synopsis=a?p.workbench.reverse_outlines[a.id]?.synopsis||'':'';return `<article class="wb-reading-unit" data-has-prose="${!!a}"><div class="wb-reading-label"><a href="${nodeLink(id)}">${id} · ${esc(n.title)}</a>${a&&p.drafts[id]?.id!==a.id&&p.drafts[id]?.created>a.created?'<span class="wb-mark">Newer draft available</span>':''}</div>${a?`<p class="wb-selected-prose">${esc(a.text)}</p><div class="wb-reverse-outline"><div><small>Intended job</small><p>${esc(n.purpose)}</p></div><div><label class="field">What this saved paragraph actually says<textarea rows="2" maxlength="1000" data-synopsis="${a.id}">${esc(synopsis)}</textarea></label><button class="btn secondary" data-save-synopsis="${a.id}">Save reverse-outline note</button><span class="tiny" role="status" data-synopsis-status="${a.id}"></span></div></div><small>${a.payload?.origin==='retained_manuscript'?'Retained manuscript passage':a.payload?.origin==='author_adaptation'?'Author adaptation of manuscript':'Selected writing version'} · ${new Date(a.created).toLocaleString()}</small>`:`<p class="wb-gap">No manuscript version selected. <a href="${nodeLink(id)}">Write or select this paragraph →</a></p><div class="wb-reverse-outline"><p>Intended job: ${esc(n.purpose)}</p></div>`}</article>`}).join('')}</div><div class="reader-question"><strong>Read across the boundaries.</strong> What question does each paragraph leave for the next one? Is a premise missing or a point repeated?</div><a class="btn secondary" href="#paper/section-${section}">Return to the section storyboard</a>`;
  $('#wb-read-section').onchange=e=>{location.hash='#paper/read-'+e.target.value};
  $('#wb-outline-toggle').onchange=e=>document.querySelectorAll('.wb-reverse-outline').forEach(x=>x.hidden=!e.target.checked);
  const gaps=()=>document.querySelectorAll('.wb-reading-unit[data-has-prose="false"]').forEach(x=>x.hidden=!$('#wb-gaps-toggle').checked);$('#wb-gaps-toggle').onchange=gaps;gaps();
  document.querySelectorAll('[data-save-synopsis]').forEach(button=>button.onclick=async()=>{const id=button.dataset.saveSynopsis,field=document.querySelector(`[data-synopsis="${id}"]`),status=document.querySelector(`[data-synopsis-status="${id}"]`);button.disabled=true;try{p.workbench=await api('/paper/reverse-outline/'+id,{base_version:p.workbench.version,synopsis:field.value},'PUT');if(current())status.textContent='Saved for this version.'}catch(e){if(current())status.textContent=e.message}finally{button.disabled=false}});
 }
 return {render};
}
